import { Table } from '@dreadnought/ui/react';
type Item = { key: number; amount: number };
const example = <Table<Item> bordered columns={[{ key: 'amount', title: 'Amount', dataIndex: 'amount' }]} dataSource={[{ key: 1, amount: 10 }]} summary={rows => <Table.Row><Table.Cell>{rows.reduce((sum, row) => sum + row.amount, 0)}</Table.Cell></Table.Row>} />;

import { Table } from '@dreadnought/ui/react';
type Person = { key: number; name: string; age: number };
const example = <Table<Person> bordered pagination={false} slotProps={{ tooltip: { openDelay: 0 } }} dataSource={[{ key: 1, name: 'Long full name', age: 29 }]} columns={[{ key: 'name', title: 'Name', dataIndex: 'name', width: 120, ellipsis: true }, { key: 'age', title: 'Age', dataIndex: 'age', align: 'right', hidden: false }]} />;

import { Table } from '@dreadnought/ui/react';
