export function Example() {
  return <Table><Table.Head><Table.Row><Table.HeaderCell scope="col">Имя</Table.HeaderCell></Table.Row></Table.Head><Table.Body><Table.Row><Table.Cell>Анна</Table.Cell></Table.Row></Table.Body></Table>;
